SET lock_timeout = '500ms';
SET statement_timeout = '700ms';

ALTER TABLE orders ADD COLUMN status text;

CREATE OR REPLACE PROCEDURE backfill_status()
LANGUAGE plpgsql
AS $$
DECLARE
    batch_size CONSTANT int := 10000;
    min_id bigint;
    max_id bigint;
    current_min bigint;
BEGIN
    SELECT min(id), max(id) INTO min_id, max_id FROM orders;
    current_min := min_id;

    WHILE current_min <= max_id LOOP
        UPDATE orders
        SET status = CASE
            WHEN cancelled_at IS NOT NULL THEN 'cancelled'
            WHEN refunded_cents > 0 AND refunded_cents >= total_cents THEN 'refunded'
            WHEN refunded_cents > 0 THEN 'partly_refunded'
            WHEN shipped_at IS NOT NULL THEN 'shipped'
            ELSE 'placed'
        END
        WHERE id >= current_min AND id < current_min + batch_size;

        COMMIT;
        current_min := current_min + batch_size;
    END LOOP;
END;
$$;

CALL backfill_status();
DROP PROCEDURE backfill_status();

ALTER TABLE orders ADD CONSTRAINT status_check CHECK (status IN ('cancelled', 'refunded', 'partly_refunded', 'shipped', 'placed')) NOT VALID;
ALTER TABLE orders VALIDATE CONSTRAINT status_check;
ALTER TABLE orders ALTER COLUMN status SET NOT NULL;

